/* ── Reset & Tokens ───────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:         #f9f8f6;
  --color-surface:    #ffffff;
  --color-border:     #e8e5e0;
  --color-text:       #1a1814;
  --color-text-muted: #6b6560;
  --color-accent:     #c84b31;
  --color-accent-dk:  #a33a23;
  --color-badge:      #1d6c4e;
  --color-badge-bg:   #e6f4ee;
  --color-deal:       #c84b31;
  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;
  --font-serif:       'Playfair Display', Georgia, serif;
  --radius-sm:        6px;
  --radius-md:        12px;
  --radius-lg:        20px;
  --shadow-card:      0 2px 12px rgba(0,0,0,.07), 0 1px 3px rgba(0,0,0,.04);
  --shadow-hover:     0 8px 32px rgba(0,0,0,.12), 0 2px 8px rgba(0,0,0,.06);
  --transition:       .22s cubic-bezier(.4,0,.2,1);
  --max-w:            1280px;
  --gap:              clamp(16px, 2.5vw, 28px);
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ── Skip Link ────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-text);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Layout Utilities ────────────────────────────────── */
.container { max-width: var(--max-w); margin-inline: auto; padding-inline: clamp(16px, 4vw, 48px); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* ── HEADER ──────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 64px;
  gap: 1rem;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-family: var(--font-serif);
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -.01em;
  justify-self: center;
}
.header-logo svg { color: var(--color-accent); }

.header-nav { display: flex; align-items: center; gap: .25rem; }
.header-nav a {
  padding: .375rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
}
.header-nav a:hover, .header-nav a:focus-visible {
  color: var(--color-text);
  background: var(--color-bg);
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
}

.header-actions { display: flex; align-items: center; gap: .5rem; justify-content: flex-end; }

.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover, .icon-btn:focus-visible {
  color: var(--color-text);
  background: var(--color-bg);
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
}
.icon-btn .badge {
  position: absolute;
  top: 5px; right: 5px;
  width: 16px; height: 16px;
  border-radius: 50%;
  background: var(--color-accent);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}

/* ── ANNOUNCEMENT BAR ─────────────────────────────────── */
.announcement-bar {
  background: var(--color-text);
  color: #fff;
  text-align: center;
  padding: .6rem 1rem;
  font-size: .8125rem;
  font-weight: 500;
  letter-spacing: .02em;
}
.announcement-bar a { text-decoration: underline; color: #ffd780; }
.announcement-bar a:focus-visible { outline: 2px solid #ffd780; outline-offset: 2px; border-radius: 2px; }

/* ── HERO ─────────────────────────────────────────────── */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 540px;
  overflow: hidden;
}

.hero-content {
  background: #f0ede8;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(40px, 6vw, 88px) clamp(32px, 5vw, 72px);
  gap: 1.5rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--color-accent);
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 24px; height: 2px;
  background: currentColor;
  border-radius: 2px;
}

.hero-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.25rem, 4.5vw, 3.75rem);
  line-height: 1.12;
  letter-spacing: -.02em;
  color: var(--color-text);
}

.hero-body {
  font-size: 1.0625rem;
  color: var(--color-text-muted);
  max-width: 38ch;
  line-height: 1.7;
}

.hero-actions { display: flex; gap: .75rem; flex-wrap: wrap; align-items: center; }

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-text);
  color: #fff;
  padding: .75rem 1.75rem;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: #333;
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0,0,0,.18);
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: transparent;
  color: var(--color-text);
  padding: .75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .9375rem;
  font-weight: 600;
  border: 1.5px solid var(--color-border);
  transition: border-color var(--transition), background var(--transition);
}
.btn-outline:hover, .btn-outline:focus-visible {
  border-color: var(--color-text);
  background: rgba(0,0,0,.04);
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

.hero-visual {
  background: #ddd8d0;
  position: relative;
  overflow: hidden;
}
.hero-visual img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .6s ease;
}
.hero-visual:hover img { transform: scale(1.03); }

.hero-tag {
  position: absolute;
  bottom: 24px; left: 24px;
  background: #fff;
  border-radius: var(--radius-md);
  padding: .75rem 1rem;
  display: flex;
  align-items: center;
  gap: .75rem;
  box-shadow: var(--shadow-card);
  font-size: .875rem;
}
.hero-tag-label { font-weight: 600; }
.hero-tag-sub { color: var(--color-text-muted); font-size: .8rem; }

/* ── SECTION COMMON ───────────────────────────────────── */
.section { padding-block: clamp(48px, 7vw, 88px); }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: clamp(24px, 3.5vw, 40px);
  flex-wrap: wrap;
}
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}
.section-subtitle {
  color: var(--color-text-muted);
  font-size: .9375rem;
  margin-top: .375rem;
  max-width: 55ch;
}
.view-all-link {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  padding: .375rem .5rem;
  border-radius: var(--radius-sm);
  transition: gap var(--transition), color var(--transition);
}
.view-all-link:hover, .view-all-link:focus-visible {
  gap: .625rem;
  color: var(--color-accent-dk);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ── CATEGORY PILLS ───────────────────────────────────── */
.category-strip {
  padding-block: 1rem 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.category-strip::-webkit-scrollbar { display: none; }
.category-list { display: flex; gap: .625rem; padding-block: .25rem; }
.category-pill {
  flex-shrink: 0;
  padding: .5rem 1.125rem;
  border-radius: 999px;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}
.category-pill:hover, .category-pill:focus-visible {
  border-color: var(--color-text);
  color: var(--color-text);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.category-pill[aria-pressed="true"] {
  background: var(--color-text);
  color: #fff;
  border-color: var(--color-text);
}

/* ── PRODUCT GRID ─────────────────────────────────────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--gap);
}

.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-3px);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 3/4;
  background: #f3f0ec;
  overflow: hidden;
}
.product-image-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-image-wrap img { transform: scale(1.06); }

.product-badges {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: .375rem;
}
.badge {
  display: inline-flex;
  align-items: center;
  padding: .25rem .625rem;
  border-radius: 999px;
  font-size: .75rem;
  font-weight: 700;
  line-height: 1;
}
.badge-new    { background: var(--color-text); color: #fff; }
.badge-sale   { background: var(--color-accent); color: #fff; }
.badge-eco    { background: var(--color-badge-bg); color: var(--color-badge); }

.product-wishlist {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,.85);
  backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition), transform var(--transition);
}
.product-wishlist:hover, .product-wishlist:focus-visible {
  color: var(--color-accent);
  background: #fff;
  transform: scale(1.1);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.product-wishlist[aria-pressed="true"] { color: var(--color-accent); }

.product-info { padding: 1rem 1.125rem 1.25rem; display: flex; flex-direction: column; gap: .375rem; flex: 1; }
.product-brand { font-size: .75rem; font-weight: 600; text-transform: uppercase; letter-spacing: .07em; color: var(--color-text-muted); }
.product-name { font-size: .9375rem; font-weight: 600; line-height: 1.35; }
.product-rating { display: flex; align-items: center; gap: .375rem; }
.stars { display: flex; gap: 2px; color: #f0a500; }
.rating-count { font-size: .8rem; color: var(--color-text-muted); }
.product-price { display: flex; align-items: baseline; gap: .5rem; margin-top: auto; padding-top: .5rem; }
.price-current { font-size: 1.0625rem; font-weight: 700; }
.price-original { font-size: .875rem; color: var(--color-text-muted); text-decoration: line-through; }
.price-save { font-size: .75rem; font-weight: 600; color: var(--color-accent); }

.product-add-btn {
  width: 100%;
  margin-top: .75rem;
  padding: .625rem;
  background: var(--color-text);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  display: flex; align-items: center; justify-content: center; gap: .5rem;
  transition: background var(--transition), transform var(--transition);
}
.product-add-btn:hover, .product-add-btn:focus-visible {
  background: var(--color-accent);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ── DEALS BAND ───────────────────────────────────────── */
.deals-section { background: var(--color-text); color: #fff; }
.deals-section .section-title { color: #fff; }
.deals-section .section-subtitle { color: rgba(255,255,255,.6); }
.deals-section .view-all-link { color: #ffd780; }
.deals-section .view-all-link:hover { color: #ffe8a6; }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--gap);
}

.deal-card {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: background var(--transition), transform var(--transition);
}
.deal-card:hover { background: rgba(255,255,255,.1); transform: translateY(-2px); }

.deal-image-wrap {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
  background: rgba(255,255,255,.04);
}
.deal-image-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
.deal-card:hover .deal-image-wrap img { transform: scale(1.05); }

.deal-discount-chip {
  position: absolute;
  top: 12px; right: 12px;
  background: var(--color-accent);
  color: #fff;
  font-size: .875rem;
  font-weight: 700;
  padding: .375rem .75rem;
  border-radius: 999px;
}

.deal-info { padding: 1.125rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
.deal-name { font-size: 1rem; font-weight: 600; line-height: 1.35; }
.deal-desc { font-size: .875rem; color: rgba(255,255,255,.6); line-height: 1.55; }
.deal-price-row { display: flex; align-items: baseline; gap: .625rem; margin-top: auto; padding-top: .625rem; }
.deal-price { font-size: 1.25rem; font-weight: 700; }
.deal-original { font-size: .875rem; color: rgba(255,255,255,.45); text-decoration: line-through; }

.deal-timer { display: flex; align-items: center; gap: .5rem; font-size: .8125rem; color: rgba(255,255,255,.55); margin-top: .25rem; }
.deal-timer svg { color: #ffd780; flex-shrink: 0; }
.deal-timer strong { color: #ffd780; }

.deal-cta {
  margin: 1rem 1.125rem 1.125rem;
  padding: .625rem;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.12);
  color: #fff;
  font-size: .875rem;
  font-weight: 600;
  display: flex; align-items: center; justify-content: center; gap: .5rem;
  transition: background var(--transition);
  border: 1px solid rgba(255,255,255,.18);
}
.deal-cta:hover, .deal-cta:focus-visible {
  background: var(--color-accent);
  border-color: transparent;
  outline: 2px solid #ffd780;
  outline-offset: 2px;
}

/* ── BANNER STRIP ─────────────────────────────────────── */
.perks-strip {
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}
.perks-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  divide-x: 1px solid var(--color-border);
}
.perk-item {
  display: flex;
  align-items: center;
  gap: .875rem;
  padding: 1.25rem 1rem;
  border-right: 1px solid var(--color-border);
}
.perk-item:last-child { border-right: none; }
.perk-icon {
  flex-shrink: 0;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-accent);
}
.perk-label { font-size: .875rem; font-weight: 600; }
.perk-sub { font-size: .8rem; color: var(--color-text-muted); margin-top: .125rem; }

/* ── EDITORIAL ────────────────────────────────────────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: auto auto;
  gap: var(--gap);
}

.editorial-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.editorial-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-2px);
}
.editorial-card:focus-within { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.editorial-card--featured { grid-row: 1 / 3; }

.editorial-image-wrap {
  overflow: hidden;
  background: #eee;
}
.editorial-card--featured .editorial-image-wrap { aspect-ratio: 4/5; }
.editorial-card:not(.editorial-card--featured) .editorial-image-wrap { aspect-ratio: 16/9; }
.editorial-image-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
.editorial-card:hover .editorial-image-wrap img { transform: scale(1.04); }

.editorial-body { padding: 1.25rem 1.375rem 1.5rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
.editorial-tag {
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--color-accent);
}
.editorial-title {
  font-family: var(--font-serif);
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.3;
}
.editorial-card--featured .editorial-title { font-size: clamp(1.25rem, 2.5vw, 1.625rem); }
.editorial-excerpt { font-size: .875rem; color: var(--color-text-muted); line-height: 1.6; }
.editorial-meta { display: flex; align-items: center; gap: .5rem; font-size: .8rem; color: var(--color-text-muted); margin-top: auto; padding-top: .5rem; }
.editorial-meta .dot { width: 3px; height: 3px; border-radius: 50%; background: currentColor; }
.editorial-read-more { display: inline-flex; align-items: center; gap: .375rem; font-size: .875rem; font-weight: 600; color: var(--color-accent); margin-top: .25rem; border-radius: 4px; }
.editorial-read-more:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.editorial-read-more:hover { gap: .625rem; }

/* ── NEWSLETTER ───────────────────────────────────────── */
.newsletter-section {
  background: linear-gradient(135deg, #f4ede4 0%, #ede6db 100%);
  padding-block: clamp(48px, 7vw, 80px);
  text-align: center;
}
.newsletter-inner { max-width: 540px; margin-inline: auto; }
