+  color: var(--color-accent);
+}
+.perk-label { font-size: .875rem; font-weight: 600; }
+.perk-sub { font-size: .8rem; color: var(--color-text-muted); margin-top: .125rem; }
+
+/* ── EDITORIAL ────────────────────────────────────────── */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr;
+  grid-template-rows: auto auto;
+  gap: var(--gap);
+}
+
+.editorial-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  box-shadow: var(--shadow-card);
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.editorial-card:hover {
+  box-shadow: var(--shadow-hover);
+  transform: translateY(-2px);
+}
+.editorial-card:focus-within { outline: 2px solid var(--color-accent); outline-offset: 2px; }
+
+.editorial-card--featured { grid-row: 1 / 3; }
+
+.editorial-image-wrap {
+  overflow: hidden;
+  background: #eee;
+}
+.editorial-card--featured .editorial-image-wrap { aspect-ratio: 4/5; }
+.editorial-card:not(.editorial-card--featured) .editorial-image-wrap { aspect-ratio: 16/9; }
+.editorial-image-wrap img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
+.editorial-card:hover .editorial-image-wrap img { transform: scale(1.04); }
+
+.editorial-body { padding: 1.25rem 1.375rem 1.5rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
+.editorial-tag {
+  font-size: .75rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .08em;
+  color: var(--color-accent);
+}
+.editorial-title {
+  font-family: var(--font-serif);
+  font-size: 1.125rem;
+  font-weight: 700;
+  line-height: 1.3;
+}
+.editorial-card--featured .editorial-title { font-size: clamp(1.25rem, 2.5vw, 1.625rem); }
+.editorial-excerpt { font-size: .875rem; color: var(--color-text-muted); line-height: 1.6; }
+.editorial-meta { display: flex; align-items: center; gap: .5rem; font-size: .8rem; color: var(--color-text-muted); margin-top: auto; padding-top: .5rem; }
+.editorial-meta .dot { width: 3px; height: 3px; border-radius: 50%; background: currentColor; }
+.editorial-read-more { display: inline-flex; align-items: center; gap: .375rem; font-size: .875rem; font-weight: 600; color: var(--color-accent); margin-top: .25rem; border-radius: 4px; }
+.editorial-read-more:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
+.editorial-read-more:hover { gap: .625rem; }
+
+/* ── NEWSLETTER ───────────────────────────────────────── */
+.newsletter-section {
+  background: linear-gradient(135deg, #f4ede4 0%, #ede6db 100%);
+  padding-block: clamp(48px, 7vw, 80px);
+  text-align: center;
+}
+.newsletter-inner { max-width: 540px; margin-inline: auto; }
+.newsletter-eyebrow {
+  font-size: .8125rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: var(--color-accent);
+  margin-bottom: .875rem;
+}
+.newsletter-title { font-family: var(--font-serif); font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 700; letter-spacing: -.01em; margin-bottom: .75rem; }
+.newsletter-body { color: var(--color-text-muted); font-size: .9375rem; margin-bottom: 1.75rem; line-height: 1.65; }
+
+.newsletter-form {
+  display: flex;
+  gap: .625rem;
+  flex-wrap: wrap;
+  justify-content: center;
+}
+.newsletter-input {
+  flex: 1 1 240px;
+  padding: .75rem 1rem;
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-sm);
+  font-size: .9375rem;
