+}
+.newsletter-submit {
+  padding: .75rem 1.5rem;
+  background: var(--color-text);
+  color: #fff;
+  border-radius: var(--radius-sm);
+  font-size: .9375rem;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition);
+  white-space: nowrap;
+}
+.newsletter-submit:hover, .newsletter-submit:focus-visible {
+  background: var(--color-accent);
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+}
+.newsletter-note { font-size: .8rem; color: var(--color-text-muted); margin-top: .875rem; }
+
+/* ── FOOTER ───────────────────────────────────────────── */
+.site-footer { background: var(--color-text); color: rgba(255,255,255,.7); padding-block: clamp(40px, 6vw, 64px) 0; }
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.5fr 1fr 1fr 1fr;
+  gap: var(--gap);
+  padding-bottom: clamp(32px, 4vw, 48px);
+}
+.footer-brand-col { display: flex; flex-direction: column; gap: 1rem; }
+.footer-logo {
