/* ── SECTION COMMON ───────────────────────────────────── */
.section { padding-block: clamp(48px, 7vw, 88px); }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: clamp(24px, 3.5vw, 40px);
  flex-wrap: wrap;
}
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}
.section-subtitle {
  color: var(--color-text-muted);
  font-size: .9375rem;
  margin-top: .375rem;
  max-width: 55ch;
}
.view-all-link {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .875rem;
  font-weight: 600;
