function ProductCard(product) {
  const card = el('article', { className: 'product-card', ariaLabel: product.name });

  // Image
  const imgWrap = el('div', { className: 'product-image-wrap' });
  const imgEl = el('img', { src: product.image, alt: product.alt, loading: 'lazy' });
  imgWrap.append(imgEl);

  // Badge
  const badges = el('div', { className: 'product-badges' });
  const badgeMap = { sale: ['badge-sale', 'Sale'], new: ['badge-new', 'New'], eco: ['badge-eco', '♻ Eco'] };
  if (product.badge && badgeMap[product.badge]) {
    const [cls, text] = badgeMap[product.badge];
    badges.append(el('span', { className: `badge ${cls}` }, text));
  }
  imgWrap.append(badges);

  // Wishlist
  let wishlisted = false;
  const wishBtn = el('button', {
    className: 'product-wishlist',
    type: 'button',
    ariaLabel: `Add ${product.name} to wishlist`,
    ariaPressed: 'false',
  }, svg('heart', 16));
  wishBtn.addEventListener('click', () => {
    wishlisted = !wishlisted;
    wishBtn.setAttribute('aria-pressed', wishlisted ? 'true' : 'false');
    wishBtn.setAttribute('aria-label', `${wishlisted ? 'Remove' : 'Add'} ${product.name} ${wishlisted ? 'from' : 'to'} wishlist`);
    wishBtn.innerHTML = '';
    wishBtn.append(svg(wishlisted ? 'heart-filled' : 'heart', 16));
    showToast(wishlisted ? `"${product.name}" saved to wishlist` : `"${product.name}" removed from wishlist`);
  });
  imgWrap.append(wishBtn);
  card.append(imgWrap);

  // Info
  const info = el('div', { className: 'product-info' });
  info.append(el('p', { className: 'product-brand' }, product.brand));
  info.append(el('h3', { className: 'product-name' }, product.name));

  const ratingRow = el('div', { className: 'product-rating' });
  ratingRow.append(stars(product.rating));
  ratingRow.append(el('span', { className: 'rating-count' }, `(${product.reviews})`));
  info.append(ratingRow);

  const priceRow = el('div', { className: 'product-price' });
  priceRow.append(el('span', { className: 'price-current' }, `$${product.price}`));
  if (product.originalPrice) {
    const save = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);
    priceRow.append(el('span', { className: 'price-original' }, `$${product.originalPrice}`));
    priceRow.append(el('span', { className: 'price-save' }, `Save ${save}%`));
  }
  info.append(priceRow);

  const addBtn = el('button', {
    className: 'product-add-btn',
    type: 'button',
    ariaLabel: `Add ${product.name} to cart`,
  }, svg('plus', 15), 'Add to Cart');
  addBtn.addEventListener('click', () => addToCart(product.name));
  info.append(addBtn);

  card.append(info);
  return card;
}

