function el(tag, attrs = {}, ...children) {
  const elem = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'className') elem.className = v;
    else if (k === 'htmlFor') elem.htmlFor = v;
    else if (k.startsWith('aria') || k === 'role' || k === 'tabindex') elem.setAttribute(k.replace(/([A-Z])/g, '-$1').toLowerCase(), v);
    else if (k.startsWith('data')) elem.setAttribute(k, v);
    else elem[k] = v;
  }
  for (const child of children) {
    if (child == null) continue;
    elem.append(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return elem;
}

