  const header = el('div', { className: 'section-header' });
  const titleWrap = el('div', {});
  titleWrap.append(el('h2', { className: 'section-title', id: 'editorial-heading' }, 'From the Journal'));
  titleWrap.append(el('p', { className: 'section-subtitle' }, 'Stories about craft, sustainability, and style.'));
  const viewAll = el('a', { className: 'view-all-link', href: '#' }, 'All articles', svg('arrowRight', 14));
  header.append(titleWrap, viewAll);
  container.append(header);

  const grid = el('div', { className: 'editorial-grid' });
  ARTICLES.forEach(a => grid.append(ArticleCard(a)));
  container.append(grid);

  section.append(container);
  return section;
}

function Newsletter() {
  const section = el('section', { className: 'newsletter-section', ariaLabelledby: 'newsletter-heading' });
  const inner = el('div', { className: 'newsletter-inner container' });

  inner.append(el('p', { className: 'newsletter-eyebrow' }, 'Join the Community'));
  inner.append(el('h2', { className: 'newsletter-title', id: 'newsletter-heading' }, 'Get 10% off your first order'));
  inner.append(el('p', { className: 'newsletter-body' },
    'Subscribe for early access to new arrivals, exclusive member deals, and style inspiration curated just for you.'
  ));

  const form = el('form', { className: 'newsletter-form', ariaLabel: 'Newsletter sign-up form' });
  form.setAttribute('novalidate', '');

  const emailInput = el('input', {
    className: 'newsletter-input',
    type: 'email',
    id: 'newsletter-email',
    placeholder: 'Enter your email address',
    ariaLabel: 'Email address',
    ariaRequired: 'true',
    autocomplete: 'email',
  });

  const submitBtn = el('button', {
    className: 'newsletter-submit',
    type: 'submit',
  }, 'Subscribe');

  form.append(emailInput, submitBtn);

  form.addEventListener('submit', e => {
    e.preventDefault();
    const val = emailInput.value.trim();
    if (!val || !val.includes('@')) {
      emailInput.focus();
      showToast('Please enter a valid email address');
      return;
    }
    showToast('You\'re subscribed! Check your inbox for 10% off.');
    emailInput.value = '';
  });

  inner.append(form);
  inner.append(el('p', { className: 'newsletter-note' }, 'No spam, ever. Unsubscribe anytime. See our Privacy Policy.'));
  section.append(inner);
  return section;
}

function Footer() {
  const footer = el('footer', { className: 'site-footer', ariaLabel: 'Site footer' });
  const container = el('div', { className: 'container' });

  const grid = el('div', { className: 'footer-grid' });

  // Brand col
  const brandCol = el('div', { className: 'footer-brand-col' });
  brandCol.append(el('div', { className: 'footer-logo' }, svg('logo', 20), 'Maison'));
  brandCol.append(el('p', { className: 'footer-tagline' },
