  brandCol.append(socials);
  grid.append(brandCol);

  // Link columns
  const COLS = [
    { title: 'Shop', links: ['Women', 'Men', 'Kids', 'Home & Living', 'Beauty', 'Gift Cards'] },
    { title: 'Help', links: ['FAQs', 'Shipping & Returns', 'Size Guide', 'Track Order', 'Contact Us'] },
    { title: 'Company', links: ['About Us', 'Sustainability', 'Careers', 'Press', 'Affiliates'] },
  ];

  COLS.forEach(col => {
    const colEl = el('div', {});
    colEl.append(el('h3', { className: 'footer-col-title' }, col.title));
    const links = el('ul', { className: 'footer-links', role: 'list' });
    col.links.forEach(link => {
      links.append(el('li', {}, el('a', { href: '#' }, link)));
    });
    colEl.append(links);
    grid.append(colEl);
  });

  container.append(grid);

  const bottom = el('div', { className: 'footer-bottom' });
  bottom.append(el('p', {}, `© ${new Date().getFullYear()} Maison. All rights reserved.`));
  const legal = el('ul', { className: 'footer-legal', role: 'list' });
  ['Privacy Policy', 'Terms of Service', 'Cookie Preferences', 'Accessibility'].forEach(item => {
    legal.append(el('li', {}, el('a', { href: '#' }, item)));
  });
  bottom.append(legal);
  container.append(bottom);

  footer.append(container);
  return footer;
}

// ── Mount ─────────────────────────────────────────────────
function App() {
  const root = document.getElementById('app');

  const toastRegion = el('div', { id: 'toast-region', ariaLive: 'polite', ariaLabel: 'Notifications' });
  document.body.append(toastRegion);

  root.append(
    AnnouncementBar(),
    Header(),
    el('main', { id: 'main-content', tabindex: '-1' },
      Hero(),
      FeaturedProducts(),
      PerksStrip(),
      DealsSection(),
      EditorialSection(),
      Newsletter(),
    ),
    Footer()
  );
}

document.addEventListener('DOMContentLoaded', App);

