function stars(rating) {
  const wrap = el('span', { className: 'stars', role: 'img', ariaLabel: `${rating} out of 5 stars` });
  for (let i = 1; i <= 5; i++) {
    const s = svg('star');
    s.style.opacity = i <= Math.round(rating) ? '1' : '.25';
    wrap.append(s);
  }
  return wrap;
}

// ── Toast ─────────────────────────────────────────────────
function showToast(message) {
  const region = document.getElementById('toast-region');
  const toast = el('div', { className: 'toast', role: 'status', ariaLive: 'polite' }, svg('check'), message);
  region.append(toast);
  setTimeout(() => {
    toast.classList.add('toast--out');
    toast.addEventListener('animationend', () => toast.remove());
  }, 3200);
}

// ── Cart state ────────────────────────────────────────────
let cartCount = 0;
function addToCart(name) {
  cartCount++;
  document.getElementById('cart-count').textContent = cartCount;
  document.getElementById('cart-count').style.display = 'flex';
  document.getElementById('cart-btn').setAttribute('aria-label', `Shopping cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`);
  showToast(`"${name}" added to cart`);
}

