function AnnouncementBar() {
  return el('div', { className: 'announcement-bar', role: 'banner' },
    '🎁 Free shipping on all orders over $75 — ',
    el('a', { href: '#deals', ariaLabel: 'Shop deals now' }, 'Shop Deals'),
    ' · Limited-time offer'
  );
}

function Header() {
  const header = el('header', { className: 'site-header', role: 'banner' });
  const inner = el('div', { className: 'container header-inner' });

  // Nav
  const nav = el('nav', { className: 'header-nav', ariaLabel: 'Main navigation' });
  ['Women', 'Men', 'Home', 'Beauty', 'Sale'].forEach(item => {
    nav.append(el('a', { href: '#' }, item));
  });

  // Logo
  const logo = el('a', { className: 'header-logo', href: '#', ariaLabel: 'Maison — return to homepage' },
    svg('logo', 22), 'Maison'
  );

  // Actions
  const actions = el('div', { className: 'header-actions', ariaLabel: 'Site actions' });

  const searchBtn = el('button', { className: 'icon-btn', ariaLabel: 'Open search', type: 'button' }, svg('search'));
  const wishlistBtn = el('button', { className: 'icon-btn', ariaLabel: 'Wishlist', type: 'button' }, svg('heart'));
  const accountBtn = el('button', { className: 'icon-btn', ariaLabel: 'Account', type: 'button' }, svg('user'));

  const cartBadge = el('span', { className: 'badge', id: 'cart-count', ariaHidden: 'true' }, '0');
  cartBadge.style.display = 'none';
  const cartBtn = el('button', { className: 'icon-btn', id: 'cart-btn', ariaLabel: 'Shopping cart, 0 items', type: 'button' }, svg('cart'), cartBadge);

  searchBtn.addEventListener('click', () => showToast('Search coming soon'));
  wishlistBtn.addEventListener('click', () => showToast('Wishlist coming soon'));
  accountBtn.addEventListener('click', () => showToast('Sign in coming soon'));
  cartBtn.addEventListener('click', () => showToast(`Cart: ${cartCount} item${cartCount !== 1 ? 's' : ''}`));

  actions.append(searchBtn, wishlistBtn, accountBtn, cartBtn);
  inner.append(nav, logo, actions);
  header.append(inner);
  return header;
}

function Hero() {
  const section = el('section', { className: 'hero', ariaLabelledby: 'hero-heading' });

  const content = el('div', { className: 'hero-content' });
  const eyebrow = el('p', { className: 'hero-eyebrow' }, 'New Collection — Spring 2026');
  const heading = el('h1', { className: 'hero-heading', id: 'hero-heading' }, 'Crafted for\nthe everyday.');
  heading.style.whiteSpace = 'pre-line';
  const body = el('p', { className: 'hero-body' },
    'Timeless essentials made from natural fibers. Designed to last, ' +
    'built to wear every single day — season after season.'
  );

  const actions = el('div', { className: 'hero-actions' });
  const shopBtn = el('a', { className: 'btn-primary', href: '#featured' }, 'Shop New In', svg('arrowRight', 16));
  const lookBtn = el('a', { className: 'btn-outline', href: '#editorial' }, 'View Lookbook');
  actions.append(shopBtn, lookBtn);

  content.append(eyebrow, heading, body, actions);

  const visual = el('div', { className: 'hero-visual', ariaHidden: 'true' });
  const img = el('img', {
    src: 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=900&q=85',
    alt: 'Model wearing a cream knit sweater and wide-leg trousers in a sun-lit studio',
    loading: 'eager',
  });

  const tag = el('div', { className: 'hero-tag', ariaHidden: 'true' });
  const tagText = el('div', {});
  const tagLabel = el('div', { className: 'hero-tag-label' }, '⭐ Editor\'s Pick');
  const tagSub = el('div', { className: 'hero-tag-sub' }, 'Merino Wool Turtleneck');
  tagText.append(tagLabel, tagSub);
  tag.append(tagText);

  visual.append(img, tag);
  section.append(content, visual);
  return section;
}

function CategoryStrip() {
  const wrap = el('div', { className: 'category-strip container', ariaLabel: 'Filter by category' });
  const list = el('ul', { className: 'category-list', role: 'list' });

  CATEGORIES.forEach((cat, i) => {
    const pill = el('button', {
      className: 'category-pill',
      type: 'button',
      ariaPressed: i === 0 ? 'true' : 'false',
    }, cat);

    pill.addEventListener('click', () => {
      list.querySelectorAll('.category-pill').forEach(p => p.setAttribute('aria-pressed', 'false'));
      pill.setAttribute('aria-pressed', 'true');
      showToast(`Showing: ${cat}`);
    });

    list.append(el('li', {}, pill));
  });

  wrap.append(list);
  return wrap;
}

function ProductCard(product) {
  const card = el('article', { className: 'product-card', ariaLabel: product.name });

  // Image
  const imgWrap = el('div', { className: 'product-image-wrap' });
  const imgEl = el('img', { src: product.image, alt: product.alt, loading: 'lazy' });
  imgWrap.append(imgEl);

  // Badge
  const badges = el('div', { className: 'product-badges' });
  const badgeMap = { sale: ['badge-sale', 'Sale'], new: ['badge-new', 'New'], eco: ['badge-eco', '♻ Eco'] };
  if (product.badge && badgeMap[product.badge]) {
    const [cls, text] = badgeMap[product.badge];
    badges.append(el('span', { className: `badge ${cls}` }, text));
  }
  imgWrap.append(badges);

  // Wishlist
  let wishlisted = false;
  const wishBtn = el('button', {
    className: 'product-wishlist',
    type: 'button',
    ariaLabel: `Add ${product.name} to wishlist`,
    ariaPressed: 'false',
  }, svg('heart', 16));
  wishBtn.addEventListener('click', () => {
    wishlisted = !wishlisted;
    wishBtn.setAttribute('aria-pressed', wishlisted ? 'true' : 'false');
    wishBtn.setAttribute('aria-label', `${wishlisted ? 'Remove' : 'Add'} ${product.name} ${wishlisted ? 'from' : 'to'} wishlist`);
    wishBtn.innerHTML = '';
    wishBtn.append(svg(wishlisted ? 'heart-filled' : 'heart', 16));
    showToast(wishlisted ? `"${product.name}" saved to wishlist` : `"${product.name}" removed from wishlist`);
  });
  imgWrap.append(wishBtn);
  card.append(imgWrap);

  // Info
  const info = el('div', { className: 'product-info' });
  info.append(el('p', { className: 'product-brand' }, product.brand));
  info.append(el('h3', { className: 'product-name' }, product.name));

  const ratingRow = el('div', { className: 'product-rating' });
  ratingRow.append(stars(product.rating));
  ratingRow.append(el('span', { className: 'rating-count' }, `(${product.reviews})`));
  info.append(ratingRow);

  const priceRow = el('div', { className: 'product-price' });
  priceRow.append(el('span', { className: 'price-current' }, `$${product.price}`));
  if (product.originalPrice) {
    const save = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);
    priceRow.append(el('span', { className: 'price-original' }, `$${product.originalPrice}`));
    priceRow.append(el('span', { className: 'price-save' }, `Save ${save}%`));
  }
  info.append(priceRow);

  const addBtn = el('button', {
    className: 'product-add-btn',
    type: 'button',
    ariaLabel: `Add ${product.name} to cart`,
  }, svg('plus', 15), 'Add to Cart');
  addBtn.addEventListener('click', () => addToCart(product.name));
  info.append(addBtn);

  card.append(info);
  return card;
}

function FeaturedProducts() {
  const section = el('section', {
    className: 'section',
    id: 'featured',
    ariaLabelledby: 'featured-heading',
  });
  const container = el('div', { className: 'container' });

  const header = el('div', { className: 'section-header' });
  const titleWrap = el('div', {});
  titleWrap.append(el('h2', { className: 'section-title', id: 'featured-heading' }, 'Featured Products'));
  titleWrap.append(el('p', { className: 'section-subtitle' }, 'Hand-picked by our team this season.'));
  const viewAll = el('a', { className: 'view-all-link', href: '#' }, 'View all products', svg('arrowRight', 14));
  header.append(titleWrap, viewAll);
  container.append(header);

  container.append(CategoryStrip());

  const grid = el('div', { className: 'product-grid', style: 'margin-top: 1.5rem' });
  PRODUCTS.forEach(p => grid.append(ProductCard(p)));
  container.append(grid);

  section.append(container);
  return section;
}

function PerksStrip() {
  const PERKS = [
    { icon: 'truck', label: 'Free Shipping', sub: 'On orders over $75' },
    { icon: 'shield', label: 'Secure Payments', sub: '256-bit SSL encryption' },
    { icon: 'refresh', label: 'Easy Returns', sub: '30-day hassle-free returns' },
    { icon: 'tag', label: 'Members Save More', sub: 'Up to 20% off every order' },
  ];

  const strip = el('div', { className: 'perks-strip', ariaLabel: 'Shopping benefits' });
  const container = el('div', { className: 'container' });
  const list = el('ul', { className: 'perks-list', role: 'list' });

  PERKS.forEach(perk => {
    const item = el('li', { className: 'perk-item' });
    const icon = el('div', { className: 'perk-icon', ariaHidden: 'true' }, svg(perk.icon));
    const text = el('div', {});
    text.append(el('div', { className: 'perk-label' }, perk.label));
    text.append(el('div', { className: 'perk-sub' }, perk.sub));
    item.append(icon, text);
    list.append(item);
  });

  container.append(list);
  strip.append(container);
  return strip;
}

function DealCard(deal) {
  const card = el('article', { className: 'deal-card', ariaLabel: deal.name });

  const imgWrap = el('div', { className: 'deal-image-wrap' });
